WITH cleaned AS (SELECT *, UPPER(supplier_name) supplier_name_upper, LENGTH(country) country_length FROM suppliers WHERE rating BETWEEN 3.4 AND 3.6) SELECT id, supplier_name, country, supplier_name_upper, AVG(country_length) OVER (PARTITION BY city, country ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_avg_country_length, MAX(country_length) OVER (PARTITION BY city, country ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_max_country_length, MIN(country_length) OVER (PARTITION BY city, country ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_min_country_length, CUME_DIST() OVER (PARTITION BY country ORDER BY rating DESC NULLS LAST) rating_cume_dist FROM cleaned
